FILES = {'DIAGPROG5.py': 'fe08f4f0999495ec069d2cee2baa9225f7ef7226c3ebc4b8d25962f2bfdcc193', 'dp5_runtime.py': '7a4c9974d2c4c6e9841c72dfc88df401d26b271da40a0b1464712d05b58b5b91', 'dp5_publicacion.py': '5b1791462c4e541340125434c54ef74df6788eb5a4a3caa602737523249da257', 'dp5_ui.py': '311e021d04a87d9aebc64163cd3db1602d24788a203f03ca06d3e94fcb9e374e', 'dp5_actualizaciones.py': 'e6a287df54087ac69c946b7957fb6106ad8cf9a957e740324235f87054295d3a', 'borrado_antiguos.py': '5d998c90ad06233a5fa1fdd08b4bba75f385b8303acf1caa36b8c432ddb9d639', 'banner_dp5_limpio_v15.png': '87d2395cb1ebd32c38a0dc2cfdd1521e2c4485244372d0a7066b09122809bf1e'}

def extraer(data):
    data = Path(data).resolve()
    raw = base64.b85decode(PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_HASH:
        raise RuntimeError('El instalador está incompleto o dañado. No se ha modificado el programa anterior.')
    versions = data / 'versiones'
    versions.mkdir(parents=True, exist_ok=True)
    current = data / 'instalacion_actual.json'
    if current.exists():
        info = json.loads(current.read_text(encoding='utf-8'))
        if int(info.get('version',0)) > int(VERSION):
            raise RuntimeError('Hay una versión más reciente instalada. Abre esa versión.')
    stable = versions / ('V108_PRO_' + PAYLOAD_HASH[:10])
    if stable.is_dir() and all((stable/n).is_file() and hashlib.sha256((stable/n).read_bytes()).hexdigest()==sha for n,sha in FILES.items()):
        return stable/'DIAGPROG5.py'
    with zipfile.ZipFile(io.BytesIO(raw)) as package:
        if set(package.namelist()) != set(FILES):
            raise RuntimeError('El contenido del paquete no coincide con la lista de archivos.')
        for entry in package.infolist():
            if entry.filename != Path(entry.filename).name or entry.file_size > 5_000_000:
                raise RuntimeError('Ruta o tamaño de paquete no permitido.')
        dest = Path(tempfile.mkdtemp(prefix='V108_PREPARANDO_',dir=versions))
        for name, sha in FILES.items():
            contenido = package.read(name)
            if hashlib.sha256(contenido).hexdigest()!=sha:
                raise RuntimeError('Archivo dañado: '+name)
            if name.endswith('.py'):
                compile(contenido.decode('utf-8'),name,'exec')
            (dest/name).write_bytes(contenido)
    # Nunca sobrescribir una carpeta modificada por el usuario.
    if not stable.exists():
        dest.rename(stable)
        dest=stable
    return dest/'DIAGPROG5.py'

def main():
    data=Path(os.environ.get('LOCALAPPDATA') or os.environ.get('APPDATA') or Path.home())/'DIAGPROG5'
    output=extraer(data)
    # runpy NO añade por sí solo la carpeta del script al buscador de módulos.
    sys.path.insert(0,str(output.parent))
    from dp5_runtime import preparar_datos
    preparar_datos(Path(__file__).resolve().parent,data)
    os.chdir(data)
    runpy.run_path(str(output),run_name='__main__')

if __name__=='__main__':
    try:
        main()
    except Exception as error:
        import traceback
        data=Path(os.environ.get('LOCALAPPDATA') or os.environ.get('APPDATA') or Path.home())/'DIAGPROG5'
        log=data/'logs'/'error_arranque_v108.log'
